import icontract
from typing import List


@icontract.ensure(lambda result: all(result[i] <= result[i + 1] for i in range(len(result) - 1)))
@icontract.ensure(lambda a, result: sorted(result) == sorted(a))
def BubbleSort(a: List[int]) -> List[int]:
    res = list(a)
    n = len(res)
    i = n - 1
    while i > 0:
        for j in range(i):
            if res[j] > res[j + 1]:
                res[j], res[j + 1] = res[j + 1], res[j]
        i -= 1
    return res
